/* Palette: deep navy background, soft cream card, teal accent, warm coral highlight */
:root {
  --bg: #1a1f2b;
  --card-bg: #f5f0e8;
  --text: #2c3e50;
  --accent: #2a9d8f;
  --highlight: #e76f51;
  --bar-bg: #e0d8cc;
  --input-border: #b0a89c;
  --focus-ring: #2a9d8f;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: 20px;
  padding: 28px 24px;
  max-width: 640px;
  width: 100%;
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.35);
}

h1 {
  font-size: 1.7rem;
  font-weight: 700;
  margin-bottom: 4px;
  color: var(--text);
}

.subtitle {
  font-size: 1rem;
  color: #6b7a8a;
  margin-bottom: 20px;
}

.inputs {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 8px;
  margin-bottom: 24px;
}

.input-group {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.input-group label {
  font-size: 0.85rem;
  font-weight: 600;
  color: #6b7a8a;
  text-transform: uppercase;
  letter-spacing: 0.03em;
}

.input-group input {
  width: 100%;
  min-width: 0;
  padding: 8px 4px;
  font-size: 1rem;
  text-align: center;
  border: 2px solid var(--input-border);
  border-radius: 10px;
  background: #fff;
  color: var(--text);
  transition: border-color 0.15s, box-shadow 0.15s;
  appearance: textfield;
  -moz-appearance: textfield;
}

.input-group input::-webkit-outer-spin-button,
.input-group input::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}

.input-group input:hover {
  border-color: var(--accent);
}

.input-group input:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(42, 157, 143, 0.3);
}

.input-group input:active {
  border-color: var(--accent);
  background: #f0faf8;
}

.chart-container {
  margin-bottom: 24px;
}

.chart {
  display: flex;
  align-items: flex-end;
  gap: 8px;
  height: 180px;
  padding: 0 4px;
  border-bottom: 2px solid var(--input-border);
}

.bar-wrapper {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  height: 100%;
  position: relative;
}

.bar {
  width: 100%;
  background: var(--accent);
  border-radius: 6px 6px 0 0;
  transition: height 0.3s ease, background 0.2s;
  min-height: 4px;
  position: relative;
}

.bar.highlight {
  background: var(--highlight);
  box-shadow: 0 0 0 3px rgba(231, 111, 81, 0.4);
}

.bar-label {
  font-size: 0.75rem;
  font-weight: 600;
  color: #6b7a8a;
  margin-top: 6px;
  text-align: center;
}

.bar-value {
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--text);
  margin-bottom: 2px;
  position: absolute;
  top: -20px;
  left: 50%;
  transform: translateX(-50%);
  white-space: nowrap;
}

.stats {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}

.stat {
  flex: 1;
  min-width: 140px;
  background: #ede6db;
  border-radius: 12px;
  padding: 12px 16px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.stat-label {
  font-size: 0.85rem;
  font-weight: 600;
  color: #6b7a8a;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.stat-value {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text);
}

@media (max-width: 480px) {
  .card {
    padding: 20px 16px;
  }

  h1 {
    font-size: 1.4rem;
  }

  .inputs {
    gap: 4px;
  }

  .input-group label {
    font-size: 0.75rem;
  }

  .input-group input {
    padding: 6px 2px;
    font-size: 0.9rem;
  }

  .chart {
    height: 140px;
    gap: 4px;
  }

  .bar-label {
    font-size: 0.65rem;
  }

  .bar-value {
    font-size: 0.65rem;
  }

  .stat-value {
    font-size: 1.25rem;
  }
}

(function () {
  'use strict';

  const DAYS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
  const MAX_HOURS = 12;

  const inputs = [];
  for (let i = 0; i < 7; i++) {
    inputs.push(document.getElementById('day' + i));
  }

  const chartEl = document.getElementById('chart');
  const averageEl = document.getElementById('average');
  const longestEl = document.getElementById('longest');

  function getValues() {
    return inputs.map(function (input) {
      let val = parseFloat(input.value);
      if (isNaN(val)) val = 0;
      if (val < 0) val = 0;
      if (val > MAX_HOURS) val = MAX_HOURS;
      return val;
    });
  }

  function render() {
    const values = getValues();

    // Build bars
    chartEl.innerHTML = '';
    let maxVal = -1;
    let maxIndex = -1;

    values.forEach(function (val, i) {
      if (val > maxVal) {
        maxVal = val;
        maxIndex = i;
      }
    });

    values.forEach(function (val, i) {
      const wrapper = document.createElement('div');
      wrapper.className = 'bar-wrapper';

      const bar = document.createElement('div');
      bar.className = 'bar';
      // Height as percentage of max possible (12h)
      const heightPct = (val / MAX_HOURS) * 100;
      bar.style.height = heightPct + '%';
      bar.setAttribute('role', 'presentation');

      if (i === maxIndex && maxVal > 0) {
        bar.classList.add('highlight');
      }

      const valueLabel = document.createElement('span');
      valueLabel.className = 'bar-value';
      valueLabel.textContent = val.toFixed(1);

      bar.appendChild(valueLabel);
      wrapper.appendChild(bar);

      const dayLabel = document.createElement('span');
      dayLabel.className = 'bar-label';
      dayLabel.textContent = DAYS[i];
      wrapper.appendChild(dayLabel);

      chartEl.appendChild(wrapper);
    });

    // Average
    const sum = values.reduce(function (a, b) { return a + b; }, 0);
    const avg = sum / values.length;
    averageEl.textContent = avg.toFixed(1) + ' h';

    // Longest night
    if (maxVal > 0) {
      longestEl.textContent = DAYS[maxIndex] + ' (' + maxVal.toFixed(1) + ' h)';
    } else {
      longestEl.textContent = '–';
    }

    // Update chart aria-label
    chartEl.setAttribute('aria-label',
      'Sleep hours: ' + values.map(function (v, i) { return DAYS[i] + ' ' + v.toFixed(1); }).join(', ') +
      '. Weekly average ' + avg.toFixed(1) + ' hours.'
    );
  }

  inputs.forEach(function (input) {
    input.addEventListener('input', render);
    input.addEventListener('change', render);
  });

  // Initial render
  render();
})();
